/* Registrar descripciones de negocio · lote L001
   Solo metadatos (COMMENT ON). Termina en ROLLBACK salvo  -v aplicar=1 . */
\set ON_ERROR_STOP on
\if :{?aplicar}
\else
  \set aplicar 0
\endif
select current_database() = 'esap_db' as es_la_base \gset
\if :es_la_base
\else
  \echo 'ALTO: no estás conectado a esap_db.'
  \quit
\endif
